  async function refreshCore(){const [c,t,g]=await Promise.all([A.get('/api/admin/catalog'),A.get('/api/public/teachers'),A.get('/api/admin/groups')]);state.catalog=c.stages;state.teachers=t.teachers;state.groups=g.groups;syncAllSelects()}
