  let regTimer;$('#regSearch').oninput=()=>{clearTimeout(regTimer);regTimer=setTimeout(loadRegs,250)};$('#regStatus').onchange=loadRegs;$('#regGroup').onchange=loadRegs;
  function renderRegs(){const b=$('#regBody');b.innerHTML=state.regs.map(r=>`<tr><td><strong>${esc(r.request_code)}</strong><br><small class="muted">${esc(r.created_at)}</small></td><td>${esc(r.student_name)}<br><small>${esc(r.student_phone)}</small></td><td>${esc(r.stage_name)}<br><small>${esc(r.grade_name)} • ${esc(r.subject_text)}</small></td><td>${esc(r.group_code||'غير محددة')}<br><small>${esc(r.teacher_name||'')}</small></td><td>${esc(r.parent_name)}<br><small>${esc(r.parent_phone)}</small></td><td><span class="status status--${r.status==='cancelled'?'full':r.status==='waiting'?'limited':'available'}">${esc(statusLabel[r.status]||r.status)}</span>${r.waitlist_position?`<br><small>رقم انتظار ${r.waitlist_position}</small>`:''}</td><td class="tableActions"><button class="btn btn--small btn--soft" data-view-reg="${r.id}">فتح</button><a class="btn btn--small btn--ghost" href="https://wa.me/2${esc(r.parent_phone)}" target="_blank">واتساب</a></td></tr>`).join('')||'<tr><td colspan="7">لا توجد طلبات.</td></tr>';$$('[data-view-reg]').forEach(x=>x.onclick=()=>openRegistration(Number(x.dataset.viewReg)))}
