  // groups
  async function loadGroups(){const d=await A.get('/api/admin/groups');state.groups=d.groups;renderGroups();syncAllSelects()}
  function renderGroups(){$('#groupBody').innerHTML=state.groups.map(g=>`<tr><td><strong>${esc(g.code)}</strong></td><td>${esc(g.subject_text)}<br><small>${esc(g.stage_name)} • ${esc(g.grade_name)}</small></td><td>${esc(g.teacher_name||'—')}</td><td>${esc([g.days,g.time].filter(Boolean).join(' • ')||'—')}</td><td><strong>${g.enrolled}/${g.capacity}</strong><br><small>متبقي ${g.remaining}</small></td><td>${g.waiting||0}</td><td class="tableActions"><button class="btn btn--small btn--soft" data-edit-group="${g.id}">تعديل</button><button class="btn btn--small btn--ghost" data-roster="${g.id}">كشف الطلاب</button>${g.waiting&&g.remaining?`<button class="btn btn--small btn--primary" data-promote="${g.id}">ترقية انتظار</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">لا توجد مجموعات.</td></tr>';$$('[data-edit-group]').forEach(x=>x.onclick=()=>editGroup(Number(x.dataset.editGroup)));$$('[data-roster]').forEach(x=>x.onclick=()=>groupRoster(Number(x.dataset.roster)));$$('[data-promote]').forEach(x=>x.onclick=async()=>{try{await A.post(`/api/admin/groups/${x.dataset.promote}/promote-waitlist`,{});await Promise.all([loadGroups(),loadRegs(),loadDashboard()]);notice('تمت ترقية قائمة الانتظار حسب الأماكن المتاحة',true)}catch(e){notice(e.message)}})}
